#include <stdio.h>
/* ex07：时分复用 TDM——把时间切成时隙，每路固定占一格
 * E1（欧洲标准）：每秒 8000 帧，每帧 32 个时隙，每时隙 8 bit
 *   -> 8000 × 32 × 8 = 2.048 Mbps
 * T1（北美标准）：每秒 8000 帧，每帧 24 时隙 + 1 同步位，每时隙 8 bit
 *   -> 8000 × (24×8 + 1) = 1.544 Mbps
 * 关键：每路速率 = 8000 × 8 = 64 kbps（一路话音）。*/
int main(void) {
    int frames = 8000;                 /* 每秒帧数（话音采样率 8kHz） */
    int bits_per_slot = 8;             /* 每时隙 8 bit = 1 字节 */

    printf("时分复用 TDM 容量计算（帧率 %d 帧/秒，每时隙 %d bit）\n", frames, bits_per_slot);
    printf("------------------------------------------------------------------\n");
    printf("%-14s %-10s %-12s %-14s %s\n", "标准", "时隙数", "每帧比特", "总速率", "有效话路");

    /* E1：32 时隙，其中 0 号用于同步、16 号用于信令，30 路话音 */
    int e1_slots = 32, e1_bits = e1_slots * bits_per_slot;
    printf("%-14s %-10d %-12d %-14s %d\n", "E1", e1_slots, e1_bits, "2.048 Mbps", 30);

    /* T1：24 时隙 + 1 个帧同步位 */
    int t1_slots = 24, t1_bits = t1_slots * bits_per_slot + 1;
    printf("%-14s %-10d %-12d %-14s %d\n", "T1", t1_slots, t1_bits, "1.544 Mbps", 24);

    long long e1 = (long long)frames * e1_bits;
    long long t1 = (long long)frames * t1_bits;
    printf("------------------------------------------------------------------\n");
    printf("E1 精确值 = %d × %d = %lld bps\n", frames, e1_bits, e1);
    printf("T1 精确值 = %d × %d = %lld bps\n", frames, t1_bits, t1);
    printf("\n每路话音速率 = %d × %d = %d bps = 64 kbps\n", frames, bits_per_slot, frames * bits_per_slot);
    printf("\n结论：TDM 的「固定时隙」是它的优点也是缺点 ——\n");
    printf("      有数据就传、没数据时隙也空着（浪费）。\n");
    printf("      统计时分复用 STDM 改成「按需分配」，用地址标识代替固定位置。\n");
    return 0;
}
